package org.dromara.property.charge.payment.mysql;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDate;
import java.util.UUID;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

/** TASK-020B FOR UPDATE 并发与事务原子性的真实 MySQL 验收。 */
@EnabledIfEnvironmentVariable(named="ZBM_TEST_DB_URL",matches=".+")
class PaymentAllocationMySqlTest {
 private static long projectId,bindingId;private static Connection admin;
 @BeforeAll static void setup()throws Exception{admin=open();assertEquals("zbm_property_test",admin.getCatalog());projectId=id();bindingId=id();}
 @AfterAll static void cleanup()throws Exception{try(PreparedStatement s=admin.prepareStatement("DELETE FROM pm_payment_allocation WHERE project_id=?")){s.setLong(1,projectId);s.executeUpdate();}try(PreparedStatement s=admin.prepareStatement("DELETE FROM pm_payment WHERE project_id=?")){s.setLong(1,projectId);s.executeUpdate();}try(PreparedStatement s=admin.prepareStatement("DELETE FROM pm_receivable WHERE project_id=?")){s.setLong(1,projectId);s.executeUpdate();}admin.close();}

 @Test void concurrentCollectionCannotOverAllocateLockedReceivable()throws Exception{long receivable=id();insertReceivable(receivable,"RC"+receivable,"2400.00");CountDownLatch locked=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Boolean>a=pool.submit(()->collect(receivable,"2000.00",locked,release));assertTrue(locked.await(5,TimeUnit.SECONDS));Future<Boolean>b=pool.submit(()->collect(receivable,"1000.00",null,null));release.countDown();assertTrue(a.get(10,TimeUnit.SECONDS));assertFalse(b.get(10,TimeUnit.SECONDS));assertEquals("2000.00",decimal("SELECT paid_amount FROM pm_receivable WHERE id="+receivable));}finally{pool.shutdownNow();}}

 @Test void allocationFailureRollsBackPaymentAllocationAndReceivable()throws Exception{long receivable=id(),payment=id(),allocation=id();insertReceivable(receivable,"RR"+receivable,"100.00");try(Connection c=open()){c.setAutoCommit(false);try{insertPayment(c,payment,"PX"+payment,"100.00");insertAllocation(c,allocation,payment,receivable,"50.00");updatePaid(c,receivable,"50.00","PARTIAL");insertAllocation(c,id(),payment,receivable,"50.00");fail("唯一冲突应失败");}catch(SQLException expected){c.rollback();}}assertEquals(0,scalar("SELECT COUNT(*) FROM pm_payment WHERE id="+payment));assertEquals(0,scalar("SELECT COUNT(*) FROM pm_payment_allocation WHERE payment_id="+payment));assertEquals("0.00",decimal("SELECT paid_amount FROM pm_receivable WHERE id="+receivable));}

 private static boolean collect(long receivable,String requested,CountDownLatch locked,CountDownLatch release)throws Exception{try(Connection c=open()){c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement("SELECT receivable_amount,paid_amount FROM pm_receivable WHERE id=? FOR UPDATE")){s.setLong(1,receivable);try(ResultSet r=s.executeQuery()){r.next();if(locked!=null)locked.countDown();if(release!=null)release.await(5,TimeUnit.SECONDS);BigDecimal available=r.getBigDecimal(1).subtract(r.getBigDecimal(2)),amount=new BigDecimal(requested);if(amount.compareTo(available)>0){c.rollback();return false;}updatePaid(c,receivable,r.getBigDecimal(2).add(amount).toPlainString(),amount.compareTo(available)==0?"PAID":"PARTIAL");c.commit();return true;}}}}
 private static void insertReceivable(long rid,String no,String amount)throws SQLException{String sql="INSERT INTO pm_receivable(id,project_id,receivable_no,batch_id,binding_id,room_id,charge_item_id,charge_rule_id,generate_month,period_start_date,period_end_date,theoretical_start_date,theoretical_end_date,due_date,room_full_name_snapshot,charge_item_code_snapshot,charge_item_name_snapshot,charge_rule_code_snapshot,charge_rule_name_snapshot,billing_method_snapshot,billing_cycle_snapshot,price_cycle_snapshot,cycle_mode_snapshot,due_date_mode_snapshot,due_date_offset_days_snapshot,area_snapshot,unit_price_snapshot,theoretical_days,actual_days,receivable_amount,paid_amount,payment_status) VALUES(?,?,?,1,?,101,11,12,?,?,?,?,?,?,'1号楼1单元101','PROPERTY_FEE','物业费','RULE','规则','AREA','MONTH','MONTH','NATURAL','AFTER_PERIOD_START',0,100,2,31,31,?,0,'UNPAID')";try(PreparedStatement s=admin.prepareStatement(sql)){int i=1;s.setLong(i++,rid);s.setLong(i++,projectId);s.setString(i++,no);s.setLong(i++,bindingId++);LocalDate start=LocalDate.of(2026,1,1),end=LocalDate.of(2026,1,31);s.setDate(i++,Date.valueOf(start));s.setDate(i++,Date.valueOf(start));s.setDate(i++,Date.valueOf(end));s.setDate(i++,Date.valueOf(start));s.setDate(i++,Date.valueOf(end));s.setDate(i++,Date.valueOf(end));s.setBigDecimal(i,new BigDecimal(amount));s.executeUpdate();}}
 private static void insertPayment(Connection c,long payment,String no,String amount)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_payment(id,project_id,payment_no,room_id,room_full_name_snapshot,payer_name_snapshot,payment_amount,allocated_amount,payment_method,payment_time,status) VALUES(?,?,?,101,'1号楼1单元101','李四',?,0,'CASH',NOW(),'VALID')")){s.setLong(1,payment);s.setLong(2,projectId);s.setString(3,no);s.setBigDecimal(4,new BigDecimal(amount));s.executeUpdate();}}
 private static void insertAllocation(Connection c,long aid,long payment,long receivable,String amount)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_payment_allocation(id,project_id,payment_id,receivable_id,allocation_amount,allocation_time) VALUES(?,?,?,?,?,NOW())")){s.setLong(1,aid);s.setLong(2,projectId);s.setLong(3,payment);s.setLong(4,receivable);s.setBigDecimal(5,new BigDecimal(amount));s.executeUpdate();}}
 private static void updatePaid(Connection c,long rid,String paid,String status)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE pm_receivable SET paid_amount=?,payment_status=? WHERE id=?")){s.setBigDecimal(1,new BigDecimal(paid));s.setString(2,status);s.setLong(3,rid);assertEquals(1,s.executeUpdate());}}
 private static Connection open()throws SQLException{return DriverManager.getConnection(System.getenv("ZBM_TEST_DB_URL"),System.getenv("ZBM_TEST_DB_USER"),System.getenv("ZBM_TEST_DB_PASSWORD"));}private static int scalar(String sql)throws SQLException{try(Statement s=admin.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getInt(1);}}private static String decimal(String sql)throws SQLException{try(Statement s=admin.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getBigDecimal(1).toPlainString();}}private static long id(){return Math.abs(UUID.randomUUID().getMostSignificantBits()>>>1);}
}
